/* From Uiverse.io by andrew-demchenk0 - Tags: icon, animation, red, button, opacity, pause, big */
.__UIV_SCOPE__ .button {
  width: 122px;
  height: 60px;
  padding: 18px 22px 18px 20px;
  gap: 1px;
  display: flex;
  justify-content: center;
  align-items: center;
  background: #ff284818;
  border-radius: 16px;
  border: none;
  cursor: pointer;
}

.__UIV_SCOPE__ .label {
  font-family: sans-serif;
  height: 23px;
  font-size: 19px;
  line-height: 24px;
  color: #FF2849;
}

.__UIV_SCOPE__ .button:hover {
  background: #ff284839;
}

.__UIV_SCOPE__ .button:hover .svg-icon {
  animation: pulse 0.7s linear infinite;
}

@keyframes pulse {
  0% {
    transform: scale(1);
  }

  50% {
    transform: scale(1.13);
  }

  100% {
    transform: scale(1);
  }
}
